const FIELD_SEL = 'input:not([type=hidden]):not([type=submit]):not([type=button]):not([type=checkbox]):not([type=radio]), textarea, select, [contenteditable="true"]';
const readValue = (el) => el ? (el.isContentEditable ? (el.textContent || '') : String(el.value || '')) : '';
const setValue = (el, value) => {
  el.focus();
  if (el.isContentEditable) {
    el.textContent = value;
  } else {
    const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const desc = Object.getOwnPropertyDescriptor(proto, 'value');
    if (desc && desc.set) desc.set.call(el, value); else el.value = value;
  }
  el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: value }));
  el.dispatchEvent(new Event('change', { bubbles: true }));
};
// Find a visible form control by its <label> text, then by aria-label/placeholder/name/id/data-testid.
const findField = (re) => {
  for (const lab of document.querySelectorAll('label')) {
    if (!re.test(norm(lab.textContent))) continue;
    let c = lab.htmlFor ? document.getElementById(lab.htmlFor) : null;
    if (!c) c = lab.querySelector(FIELD_SEL);
    if (!c && lab.nextElementSibling && lab.nextElementSibling.matches(FIELD_SEL)) c = lab.nextElementSibling;
    if (c && c.matches(FIELD_SEL) && isVisible(c)) return c;
  }
  for (const c of document.querySelectorAll(FIELD_SEL)) {
    const hay = [c.getAttribute('aria-label'), c.getAttribute('placeholder'), c.getAttribute('name'), c.id, c.getAttribute('data-testid')].filter(Boolean).join(' ');
    if (re.test(hay) && isVisible(c)) return c;
  }
  return null;
};
const summaryField = () => findField(/summary/i) || findField(/^title\b/i);
const descriptionField = () => findField(/description/i) || findField(/\b(body|details)\b/i);
const labelsControl = () => findField(/\blabels?\b/i);
const findLabelCheckboxes = () => {
  const groups = [...document.querySelectorAll('fieldset, [role="group"]')].filter((g) => {
    const legend = g.querySelector('legend');
    return /\blabels?\b/i.test(norm((legend && legend.textContent) || g.getAttribute('aria-label') || ''));
  });
  for (const g of groups) {
    const boxes = [...g.querySelectorAll('input[type=checkbox]')];
    if (boxes.length) return boxes;
  }
  return [];
};
const boxText = (b) => norm((b.labels && b.labels[0] && b.labels[0].textContent) || b.getAttribute('aria-label') || b.value);
const applyLabels = (labels) => {
  const want = labels.map((l) => l.toLowerCase());
  const ctl = labelsControl();
  if (ctl && ctl.tagName === 'SELECT') {
    let picked = false;
    for (const o of ctl.options) {
      const hit = want.includes(norm(o.textContent).toLowerCase()) || want.includes(String(o.value).toLowerCase());
      if (ctl.multiple) o.selected = hit;
      else if (hit && !picked) { ctl.value = o.value; picked = true; }
    }
    ctl.dispatchEvent(new Event('input', { bubbles: true }));
    ctl.dispatchEvent(new Event('change', { bubbles: true }));
    return 'select';
  }
  if (ctl) { setValue(ctl, labels.join(', ')); return 'text'; }
  const boxes = findLabelCheckboxes();
  if (boxes.length) {
    for (const b of boxes) { const hit = want.includes(boxText(b).toLowerCase()); if (b.checked !== hit) b.click(); }
    return 'checkbox';
  }
  return null;
};
const labelsCheck = (labels) => {
  const want = labels.map((l) => l.toLowerCase());
  const ctl = labelsControl();
  if (ctl && ctl.tagName === 'SELECT') {
    const avail = [...ctl.options].filter((o) => want.includes(norm(o.textContent).toLowerCase()) || want.includes(String(o.value).toLowerCase()));
    if (!avail.length) return true;
    const missing = avail.filter((o) => !o.selected);
    return (ctl.multiple ? missing.length === 0 : avail.some((o) => o.selected)) ? true : 'label options not selected: ' + missing.map((o) => norm(o.textContent)).join(', ');
  }
  if (ctl) {
    const v = readValue(ctl).toLowerCase();
    const miss = want.filter((w) => !v.includes(w));
    return miss.length ? 'Labels field is missing: ' + miss.join(', ') : true;
  }
  const boxes = findLabelCheckboxes();
  if (boxes.length) {
    const unchecked = boxes.filter((b) => want.includes(boxText(b).toLowerCase()) && !b.checked);
    return unchecked.length ? 'label checkboxes unchecked: ' + unchecked.map(boxText).join(', ') : true;
  }
  return 'no Labels field found';
};
const ctlText = (el) => norm(el.tagName === 'INPUT' ? el.value : (el.textContent || el.getAttribute('aria-label')));
const findOpener = () => {
  const cands = [...document.querySelectorAll('a, button, [role="button"], [role="link"]')].filter(isVisible);
  return cands.find((el) => /^(create|new)\s+(issue|ticket)$/i.test(ctlText(el))) || cands.find((el) => /^(\+\s*)?(create|new)\b/i.test(ctlText(el)));
};
const findCreateButton = () => {
  const summary = summaryField();
  const scope = (summary && summary.closest('form, [role="dialog"]')) || document;
  const cands = [...scope.querySelectorAll('button, input[type=submit], [role="button"]')].filter(isVisible);
  return cands.find((b) => /^create$/i.test(ctlText(b))) || cands.find((b) => /^create\b/i.test(ctlText(b))) || cands.find((b) => b.type === 'submit' && /create|save|submit/i.test(ctlText(b)));
};
const findTicketHeading = (summary) => {
  const needle = norm(summary).toLowerCase().slice(0, 80);
  if (!needle) return null;
  for (const h of document.querySelectorAll('h1, h2, h3, [data-testid*="summary" i], [data-testid*="title" i]')) {
    if (h.closest('form')) continue;
    if (isVisible(h) && norm(h.textContent).toLowerCase().includes(needle)) return h;
  }
  return null;
};
const KEY_RE = /\b[A-Z][A-Z0-9]{1,9}-\d+\b/;
const extractTicketId = (heading) => {
  const near = heading && heading.parentElement ? norm(heading.parentElement.innerText || heading.parentElement.textContent) : '';
  const k1 = near.match(KEY_RE);
  if (k1) return k1[0];
  const u = new URL(location.href);
  for (const k of ['key', 'id', 'ticket', 'issue', 'n']) { const v = u.searchParams.get(k); if (v) return v; }
  const hash = location.hash.match(/[A-Za-z0-9-]*\d+/);
  if (hash) return hash[0];
  const scope = (heading && heading.closest('article, section, main, [role="main"]')) || document.body;
  const text = norm(scope.innerText || scope.textContent);
  const k2 = text.match(KEY_RE) || near.match(/#\d+\b/) || text.match(/#\d+\b/);
