WidgetAI.flow.handle('createTicket', async (input, ctx) => {
  const summary = norm(input && input.summary).slice(0, 250);
  const description = String((input && input.description) || '').slice(0, 8000);
  const labels = Array.isArray(input && input.labels) ? input.labels.map(norm).filter(Boolean).slice(0, 20) : [];
  if (!summary) return { ok: false, evidence: { url: location.href }, error: 'No summary was provided' };
  const resume = ctx.resumeState;
  let formUrl = (resume && resume.formUrl) || location.href;

  if (!resume || resume.phase !== 'submitted') {
    const fill = await WidgetAI.run('Fill the tracker Create issue form', async (state) => {
      state.summary = summary;
      state.description = description;
      state.labels = labels;
      state = await WidgetAI.step('open-create-form', {
        state,
        goal: 'Make the tracker Create issue form (its Summary field) visible',
        run: async (s) => {
          if (summaryField()) return s;
          await sleep(800);
          if (summaryField()) return s;
          const opener = findOpener();
          if (opener) {
            const href = opener.tagName === 'A' ? (opener.getAttribute('href') || '') : '';
            if (href && !href.startsWith('#')) await ctx.checkpoint({ phase: 'opening' });
            opener.click();
          }
          return s;
        },
        expect: { check: () => summaryField() ? true : 'no visible Summary field; view: ' + dumpView().slice(0, 200), description: 'Summary input is visible' },
        branches: [
          { id: 'aria-opener', when: 'the create control is an icon button identified only by aria-label or title', run: async (s, h) => {
            const el = h.$$('[aria-label], [title]').find((e) => /create|new (issue|ticket)/i.test(e.getAttribute('aria-label') || e.getAttribute('title') || '') && h.visible(e));
            if (el) h.click(el);
            return s;
          } },
          { id: 'wait-longer', when: 'the tracker page is still loading', run: async (s, h) => {
            try { await h.waitFor(() => summaryField(), 8000); } catch (e) { /* postcondition decides */ }
            return s;
          } }
        ],
        region: 'body',
        timeoutMs: 8000
      });
      state = await WidgetAI.step('fill-summary', {
        state,
        goal: 'Put the issue title into the Summary field',
        run: async (s) => { const el = summaryField(); if (el && norm(readValue(el)) !== norm(s.summary)) setValue(el, s.summary); return s; },
        expect: { check: (s) => { const el = summaryField(); if (!el) return 'Summary field not found'; return norm(readValue(el)) === norm(s.summary) ? true : 'Summary holds "' + readValue(el).slice(0, 60) + '"'; }, description: 'Summary equals the issue title' },
        branches: [
          { id: 'type-text', when: 'the field ignores programmatic value changes', run: async (s, h) => { const el = summaryField(); if (el) { setValue(el, ''); await h.typeText(el, s.summary); } return s; } }
        ],
        region: 'body',
        timeoutMs: 4000
      });
      state = await WidgetAI.step('fill-description', {
        state,
        goal: 'Put the issue body and the link back to the issue into the Description field',
        run: async (s) => { const el = descriptionField(); if (el && norm(readValue(el)) !== norm(s.description)) setValue(el, s.description); return s; },
        expect: { check: (s) => { const el = descriptionField(); if (!el) return 'Description field not found'; return norm(readValue(el)) === norm(s.description) ? true : 'Description holds ' + readValue(el).length + ' chars, expected ' + s.description.length; }, description: 'Description equals body + issue link' },
        branches: [
          { id: 'type-text', when: 'the field ignores programmatic value changes', run: async (s, h) => { const el = descriptionField(); if (el) { setValue(el, ''); await h.typeText(el, s.description); } return s; } }
        ],
        region: 'body',
        timeoutMs: 4000
      });
      if (state.labels.length) {
        state = await WidgetAI.step('fill-labels', {
          state,
          goal: 'Apply the issue labels in the Labels field',
          run: async (s) => {
            if (labelsCheck(s.labels) === true) return s;
            s.labelsKind = applyLabels(s.labels);
            return s;
          },
          expect: { check: (s) => labelsCheck(s.labels), description: 'issue labels are set in the Labels field' },
          branches: [
            { id: 'labels-checkbox-group', when: 'labels are checkboxes inside a group not marked as a fieldset', run: async (s, h) => {
              const want = s.labels.map((l) => l.toLowerCase());
              for (const b of h.$$('input[type=checkbox]')) { if (want.includes(boxText(b).toLowerCase()) && !b.checked) h.click(b); }
              return s;
            } },
            { id: 'labels-comma-text', when: 'the labels input needs typed text', run: async (s, h) => { const el = labelsControl(); if (el && el.tagName !== 'SELECT') { setValue(el, ''); await h.typeText(el, s.labels.join(', ')); } return s; } }
          ],
          region: 'body',
          timeoutMs: 4000
        });
      }
      return state;
    });
    if (!fill.ok) {
      WidgetAI.log('Tracker view:\n' + dumpView(), 'warn');
      return { ok: false, evidence: { url: location.href, text: dumpView() }, error: fill.narrative || fill.error || 'Could not fill the Create issue form' };
    }
    if (await ctx.cancelled()) throw new Error('Cancelled before creating the ticket');
    const createBtn = findCreateButton();
    if (!createBtn) {
      WidgetAI.log('Create button not found. View:\n' + dumpView(), 'warn');
      return { ok: false, evidence: { url: location.href, text: dumpView() }, error: 'Create button not found on the tracker form' };
    }
    formUrl = location.href;
    await ctx.checkpoint({ phase: 'submitted', formUrl, summary, ts: Date.now() });
    WidgetAI.log('Clicking Create in the tracker...');
    createBtn.click();
    await transition(() => location.href !== formUrl || !summaryField() || findTicketHeading(summary), 6000);
  } else {
    WidgetAI.log('Resumed after page load - verifying the already submitted ticket (no re-submit).');
  }

  const rb = await WidgetAI.run('Confirm the new ticket page', async (state) => {
    state.summary = summary;
    state = await WidgetAI.step('confirm-ticket', {
      state,
      goal: 'The new ticket page is shown with a heading containing the summary',
      run: async (s) => s,
      expect: { check: (s) => findTicketHeading(s.summary) ? true : 'no ticket heading containing the summary yet (url ' + location.href + ')', description: 'ticket page heading shows the summary' },
      branches: [
        { id: 'open-from-list', when: 'the tracker shows a ticket list instead of the new ticket page', run: async (s, h) => {
          const needle = norm(s.summary).toLowerCase().slice(0, 80);
          const a = h.$$('a[href]').find((el) => norm(el.textContent).toLowerCase().includes(needle) && h.visible(el));
          if (a) h.click(a);
          return s;
        } },
        { id: 'wait-slow-save', when: 'the save is still in progress', run: async (s, h) => { await h.sleep(3000); return s; } }
      ],
      region: 'body',
      timeoutMs: 15000
    });
    return state;
  });
  const heading = rb.ok ? findTicketHeading(summary) : null;
  if (!heading) {
    WidgetAI.log('Could not confirm the ticket. View:\n' + dumpView(), 'warn');
    return { ok: false, evidence: { url: location.href, text: dumpView() }, error: rb.narrative || rb.error || 'New ticket page not confirmed' };
  }
  const id = extractTicketId(heading);
  let url = location.href;
  if (url === formUrl && id) {
    const bare = id.replace(/^#/, '');
    const a = [...document.querySelectorAll('a[href]')].find((el) => el.href.includes(bare) && /^https?:\/\//i.test(el.href));
    if (a) url = a.href;
  }
  WidgetAI.log('Ticket created: ' + (id || '(no id shown)') + ' - ' + url);
  return { ok: true, evidence: { url, id, text: norm(heading.textContent).slice(0, 200) } };
});
